-- DarkChaos: rebuild level-indexed player GT* tables for level 255 (generated by tools/extend_gt_regen_to_255.py).
-- Source: pristine retail GT_WOTLK extracts (clean per-block data). Levels 1-80 are the retail values.
-- Above 80: combat ratings cost more per 1% in step with the gear ladder, and crit per agility / intellect
-- falls in step with primary stats (both curves from tools/balance/gen_reference.py), so gear of a
-- character's own level gives the percentages it gives at 80. Mana regen per spirit follows
-- anchor(L80)*(80/L)^0.5; HP regen, NPC mana cost and barber cost are held flat past their anchor.
-- Tables in this file: gtcombatratings_dbc, gtchancetomeleecrit_dbc, gtchancetospellcrit_dbc.
-- 0-based ID = block*255 + (level-1). Re-running replaces every row of those tables.
-- Apply to acore_world, then restart the worldserver. The clients need the matching gt*.dbc files.

-- gtcombatratings_dbc: retail 1..80 preserved + L80 value times gear growth above L80 (0-based, 32 blocks x 255)
DELETE FROM `gtcombatratings_dbc`;

-- gtchancetomeleecrit_dbc: retail 1..80 preserved + L80 value divided by primary stat growth above L80 (0-based, 11 blocks x 255)
DELETE FROM `gtchancetomeleecrit_dbc`;

-- gtchancetospellcrit_dbc: retail 1..80 preserved + L80 value divided by primary stat growth above L80 (0-based, 11 blocks x 255)
DELETE FROM `gtchancetospellcrit_dbc`;
